-- PT110-S3-Q3. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT110-S3-Q3$batch04$ AND q.stimulus=$batch04$Sigatoka disease drastically reduces the yield of banana trees and is endemic throughout the areas of the world where bananas are grown. The fungus that causes the disease can be controlled with fungicides, but the fungicides can pose a health hazard to people living nearby. The fungicides are thus unsuitable for small banana groves in populated areas. Fortunately, most large banana plantations are in locations so isolated that fungicides can be used safely there. Therefore, most of the world’s banana crop is not seriously threatened by Sigatoka disease.$batch04$ AND q.prompt=$batch04$Which one of the following is an assumption on which the argument depends?$batch04$ AND q.correct_choice=$batch04$B$batch04$) THEN RAISE EXCEPTION 'Question changed: PT110-S3-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT110-S3-Q3$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT110-S3-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT110-S3-Q3$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Conclusion$batch04$, $batch04$Most of the world's banana crop is not seriously threatened by Sigatoka disease.$batch04$), (1, $batch04$Evidence$batch04$, $batch04$Fungicides control the disease but are unsafe near populated areas, so small groves in those areas cannot use them. Most large plantations are isolated enough to use fungicides safely.$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$The evidence protects *large plantations*. The conclusion is about *most of the world's banana crop*. Those match only if large plantations grow most of the bananas.$batch04$), (3, $batch04$Goal$batch04$, $batch04$A link: large plantations produce most of the world's bananas.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT110-S3-Q3$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Breeding resistant bananas someday is not part of the argument, which relies on fungicides.$batch04$), ($batch04$B$batch04$, $batch04$Negate it: large plantations do *not* produce most of the world's bananas. Then protecting them does not protect most of the crop, and the conclusion falls apart.$batch04$), ($batch04$C$batch04$, $batch04$The argument relies on fungicides. It does not need the disease to spread more slowly on plantations.$batch04$), ($batch04$D$batch04$, $batch04$The conclusion is only about Sigatoka. Other diseases do not matter.$batch04$), ($batch04$E$batch04$, $batch04$Where the unexposed trees grow does not affect how much of the crop is protected.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT110-S3-Q3$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
